import { useState } from 'react';
import dayjs from 'dayjs';

const useCalendarNavigation = () => {
  const [currentMonth, setCurrentMonth] = useState(dayjs().month());
  const [currentYear, setCurrentYear] = useState(dayjs().year());
  const [cellPages, setCellPages] = useState({});

  const goToPrevMonth = () => {
    if (currentMonth === 0) {
      setCurrentMonth(11);
      setCurrentYear(currentYear - 1);
    } else {
      setCurrentMonth(currentMonth - 1);
    }
    // Reset pagination when changing months
    setCellPages({});
  };

  const goToNextMonth = () => {
    if (currentMonth === 11) {
      setCurrentMonth(0);
      setCurrentYear(currentYear + 1);
    } else {
      setCurrentMonth(currentMonth + 1);
    }
    // Reset pagination when changing months
    setCellPages({});
  };

  const handlePageChange = (dateString, direction, e) => {
    // Prevent event bubbling to avoid triggering date selection
    e?.stopPropagation();

    setCellPages(prevPages => {
      const currentPage = prevPages[dateString] || 0;
      return {
        ...prevPages,
        [dateString]: direction === 'next' ? currentPage + 1 : Math.max(0, currentPage - 1)
      };
    });
  };

  return {
    currentMonth,
    currentYear,
    cellPages,
    goToPrevMonth,
    goToNextMonth,
    handlePageChange,
  };
};

export default useCalendarNavigation;
